    std::string line;
    std::size_t count = 0;

    while (getline(file, line)) {
        std::size_t found = std::count(std::begin(line), std::end(line), word[0]);
        while (found != 0) {
            std::size_t pos = line.find(word, found);
            if (pos == std::string::npos) {
                break;
            }
            if (std::equal(std::begin(word), std::end(word), std::begin(line), std::end(line), pos)) {
                count++;
                found = line.find(word, pos + 1);
            } else {
                found = std::string::npos;
            }
        }
